+// Helper for summarizing uncommon_trap arguments.
+void MachSafePointNode::dump_trap_args(outputStream *st) const {
+  int trap_req;
+  if (is_uncommon_trap(&trap_req)) {
+    char buf[100];
+    st->print("(%s)",
+               Deoptimization::format_trap_request(buf, sizeof(buf),
+                                                   trap_req));
+  }
+}
+
+#endif
