+#ifndef PRODUCT
+void MachUncommonTrapNode::format(PhaseRegAlloc* ra, outputStream* st) const {
+  st->print("UNCOMMON TRAP");
+
+  dump_trap_args(st);
+  st->cr();
+  format_jvms_and_oopmap(ra, st);
+}
