+    : MachSafePointNode(), _trap_request(trap_request) {
+    init_class_id(Class_MachUncommonTrap);
+  }
+
+  int trap_request() const { return _trap_request; }
+
+  virtual int ideal_Opcode() const { return Op_SafePoint; }
